func (q *Queries) LockOpenAlerts(ctx context.Context) ([]AdminAlert, error) {
	rows, err := q.db.Query(ctx, lockOpenAlerts)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AdminAlert{}
	for rows.Next() {
		var i AdminAlert
		if err := rows.Scan(
			&i.ID,
			&i.Kind,
			&i.Severity,
			&i.Value,
			&i.OpenedAt,
			&i.LastSeenAt,
			&i.ResolvedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockOwners = `-- name: LockOwners :many
SELECT id FROM platform_admins WHERE role = 'owner' AND status = 'active' ORDER BY id FOR UPDATE
`

// The active owners, locked: the last one may not be demoted or disabled.
func (q *Queries) LockOwners(ctx context.Context) ([]ulid.ID, error) {
	rows, err := q.db.Query(ctx, lockOwners)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ulid.ID{}
	for rows.Next() {
		var id ulid.ID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

